/* Question banks for the quick-fire games (Market Reaction, Excel, Up or Down, Multiples). Written for this site.
   Market reactions describe average effects found in the M&A literature, not predictions for a single deal.
   Item: {q: question, o: options, a: index of the right option, w: why}. For true/false items o is TF. */
var TF=[L('True','Wahr'),L('False','Falsch')];
var DIR3=['↑ '+L('Up','Steigt'),'↓ '+L('Down','Sinkt'),'→ '+L('No change','Unverändert')];

var MARKET_BANK=[
 {q:L('On average, target shareholders earn large positive returns when a deal is announced.','Im Durchschnitt erzielen die Aktionäre des Targets bei Ankündigung eines Deals hohe positive Renditen.'),o:TF,a:0,w:L('Targets typically jump towards the offer price; premiums of 20–40% are common.','Targets springen meist Richtung Angebotspreis; Prämien von 20–40 % sind üblich.')},
 {q:L('On average, acquirer shareholders earn large positive returns at announcement.','Im Durchschnitt erzielen die Aktionäre des Käufers bei Ankündigung hohe positive Renditen.'),o:TF,a:1,w:L('Acquirer returns are close to zero or slightly negative on average: most of the value goes to the target.','Die Renditen des Käufers liegen im Schnitt bei null oder leicht darunter: der Großteil des Werts geht an das Target.')},
 {q:L('Acquirer returns at announcement are on average better in cash deals than in stock deals.','Die Renditen des Käufers bei Ankündigung sind im Schnitt bei Cash-Deals besser als bei Aktien-Deals.'),o:TF,a:0,w:L('Paying with stock can signal that the acquirer thinks its own shares are overvalued, so stock deals see weaker reactions.','Mit Aktien zu zahlen kann signalisieren, dass der Käufer die eigenen Aktien für überbewertet hält; Aktien-Deals werden deshalb schwächer aufgenommen.')},
 {q:L('Target shareholders on average receive higher premiums in stock offers than in cash offers.','Target-Aktionäre erhalten im Schnitt höhere Prämien bei Aktienangeboten als bei Barangeboten.'),o:TF,a:1,w:L('Cash offers tend to carry higher premiums: they are certain in value and taxable for the seller, and they signal confidence.','Barangebote tragen eher höhere Prämien: ihr Wert ist sicher, sie sind für Verkäufer steuerpflichtig und signalisieren Zuversicht.')},
 {q:L('Paying with stock signals that management thinks its shares are undervalued.','Mit Aktien zu zahlen signalisiert, dass das Management seine Aktien für unterbewertet hält.'),o:TF,a:1,w:L('The opposite: you use the currency you think is expensive. Undervalued shares are a reason to pay cash.','Umgekehrt: man zahlt mit der Währung, die man für teuer hält. Unterbewertete Aktien sprechen für Barzahlung.')},
 {q:L('Hostile bids usually come with higher premiums than friendly deals.','Feindliche Angebote haben meist höhere Prämien als freundliche Deals.'),o:TF,a:0,w:L('A hostile bidder has to convince shareholders over the board, so it usually pays more.','Ein feindlicher Bieter muss die Aktionäre gegen den Vorstand überzeugen und zahlt deshalb meist mehr.')},
 {q:L('Target bondholders gain most when the target’s debt is risky and a much stronger acquirer takes it over.','Anleihegläubiger des Targets gewinnen am meisten, wenn das Target riskant verschuldet ist und ein deutlich stärkerer Käufer übernimmt.'),o:TF,a:0,w:L('The bonds get backed by a stronger balance sheet: lower default risk, higher bond price. Safe debt has little room to improve.','Die Anleihen stehen dann hinter einer stärkeren Bilanz: geringeres Ausfallrisiko, höherer Kurs. Sichere Anleihen haben wenig Luft nach oben.')},
 {q:L('Target bondholders typically gain in a leveraged buyout.','Anleihegläubiger des Targets gewinnen typischerweise bei einem LBO.'),o:TF,a:1,w:L('An LBO piles new debt on the company. Existing bonds become riskier and fall, unless covenants or a change-of-control put protect them.','Ein LBO lädt der Firma neue Schulden auf. Bestehende Anleihen werden riskanter und fallen, außer Covenants oder ein Change-of-Control-Put schützen sie.')},
 {q:L('A change-of-control put at 101% protects target bondholders in an LBO.','Ein Change-of-Control-Put zu 101 % schützt Anleihegläubiger des Targets bei einem LBO.'),o:TF,a:0,w:L('Bondholders can sell the bonds back at 101% of par when control changes, so the new leverage cannot hurt them much.','Gläubiger können die Anleihen bei Kontrollwechsel zu 101 % des Nennwerts zurückgeben; die neue Verschuldung schadet ihnen kaum.')},
 {q:L('With the same credit improvement, a long-dated target bond gains more in price than one that matures next year.','Bei gleicher Verbesserung der Bonität gewinnt eine lang laufende Target-Anleihe mehr an Kurs als eine, die nächstes Jahr fällig wird.'),o:TF,a:0,w:L('Longer maturity means higher duration: a fall in the credit spread moves the price more.','Längere Laufzeit heißt höhere Duration: ein sinkender Credit Spread bewegt den Kurs stärker.')},
 {q:L('Acquirer bondholders gain when a highly rated acquirer buys a risky target with new debt.','Anleihegläubiger des Käufers gewinnen, wenn ein gut gerateter Käufer ein riskantes Target mit neuen Schulden kauft.'),o:TF,a:1,w:L('More debt and a riskier business: the acquirer’s credit gets worse, its bonds tend to fall.','Mehr Schulden und ein riskanteres Geschäft: die Bonität des Käufers verschlechtert sich, seine Anleihen fallen eher.')},
 {q:L('Diversifying acquisitions into unrelated industries have on average been rewarded by the market.','Diversifizierende Übernahmen in fremde Branchen wurden vom Markt im Schnitt belohnt.'),o:TF,a:1,w:L('Conglomerates often trade at a discount; investors can diversify themselves more cheaply.','Konglomerate notieren oft mit Abschlag; Anleger können selbst günstiger diversifizieren.')},
 {q:L('In a cash deal, merger arbitrageurs buy the target and short the acquirer.','Bei einem Cash-Deal kaufen Merger-Arbitrageure das Target und shorten den Käufer.'),o:TF,a:1,w:L('In a cash deal they just buy the target and earn the spread to the offer price. Shorting the acquirer is the hedge in stock deals.','Bei einem Cash-Deal kaufen sie nur das Target und verdienen den Spread zum Angebotspreis. Den Käufer shorten sie bei Aktien-Deals.')},
 {q:L('In a fixed exchange ratio stock deal, arbitrageurs short the acquirer to hedge.','Bei einem Aktien-Deal mit festem Umtauschverhältnis shorten Arbitrageure den Käufer zur Absicherung.'),o:TF,a:0,w:L('Long target, short exchange ratio × acquirer shares: they lock in the spread whatever the acquirer’s price does.','Long Target, short Umtauschverhältnis × Käuferaktien: so sichern sie den Spread, egal wie sich der Käuferkurs bewegt.')},
 {q:L('After a cash offer, the target usually trades slightly below the offer price.','Nach einem Barangebot notiert das Target meist leicht unter dem Angebotspreis.'),o:TF,a:0,w:L('The gap (the arbitrage spread) pays for time value and the risk that the deal fails.','Die Lücke (Arbitrage-Spread) vergütet Zeitwert und das Risiko, dass der Deal scheitert.')},
 {q:L('If the target trades above the offer price, the market expects a higher bid.','Notiert das Target über dem Angebotspreis, erwartet der Markt ein höheres Angebot.'),o:TF,a:0,w:L('A price above the offer means investors bet on a bump or a rival bidder.','Ein Kurs über dem Angebot heißt: Anleger setzen auf eine Erhöhung oder einen Konkurrenten.')},
 {q:L('Large acquirers tend to have lower announcement returns than small acquirers.','Große Käufer haben tendenziell niedrigere Ankündigungsrenditen als kleine.'),o:TF,a:0,w:L('A well-known size effect: large firms pay higher premiums and are more prone to empire building.','Ein bekannter Größeneffekt: große Firmen zahlen höhere Prämien und neigen eher zum Empire Building.')},
 {q:L('Buying private targets has on average gone better for acquirers than buying listed targets.','Der Kauf privater Targets lief für Käufer im Schnitt besser als der Kauf börsennotierter Targets.'),o:TF,a:0,w:L('Private targets are less liquid and have fewer bidders, so they are often bought at a discount.','Private Targets sind weniger liquide und haben weniger Bieter; sie werden oft mit Abschlag gekauft.')},
 {q:L('Earn-outs are mainly used when buyer and seller agree on the value.','Earn-outs werden vor allem genutzt, wenn Käufer und Verkäufer sich über den Wert einig sind.'),o:TF,a:1,w:L('They bridge disagreement: part of the price depends on future results.','Sie überbrücken Uneinigkeit: ein Teil des Preises hängt von künftigen Ergebnissen ab.')},
 {q:L('In a fixed exchange ratio deal, target shareholders carry part of the acquirer’s price risk.','Bei festem Umtauschverhältnis tragen die Target-Aktionäre einen Teil des Kursrisikos des Käufers.'),o:TF,a:0,w:L('They get a fixed number of acquirer shares, so the value of the offer moves with the acquirer’s price.','Sie bekommen eine feste Zahl Käuferaktien; der Wert des Angebots schwankt mit dem Käuferkurs.')},
 {q:L('A fixed-value collar keeps the number of shares issued constant.','Ein Collar mit festem Wert hält die Zahl der ausgegebenen Aktien konstant.'),o:TF,a:1,w:L('A fixed-value deal adjusts the number of shares so the value stays constant within the collar.','Bei festem Wert passt sich die Zahl der Aktien an, damit der Wert innerhalb des Collars gleich bleibt.')},
 {q:L('A pre-bid stake (toehold) raises a bidder’s chance of winning a contest.','Eine Beteiligung vor dem Angebot (Toehold) erhöht die Chance eines Bieters, ein Bieterrennen zu gewinnen.'),o:TF,a:0,w:L('The toehold profits if a rival wins, so the holder can bid more aggressively.','Der Toehold gewinnt auch, wenn ein Konkurrent siegt; der Inhaber kann deshalb aggressiver bieten.')},
 {q:L('Competition among several bidders tends to raise the target premium.','Wettbewerb mehrerer Bieter erhöht tendenziell die Prämie für das Target.'),o:TF,a:0,w:L('That is why sellers run auctions.','Deshalb führen Verkäufer Auktionen durch.')},
 {q:L('The winner’s curse means the winning bidder tends to overpay.','Der Fluch des Gewinners bedeutet, dass der siegreiche Bieter tendenziell zu viel zahlt.'),o:TF,a:0,w:L('The bidder with the most optimistic estimate wins, so the winning price is often above true value.','Es gewinnt der Bieter mit der optimistischsten Schätzung; der Siegerpreis liegt deshalb oft über dem wahren Wert.')},
 {q:L('Announcing a new share issue usually lifts the share price.','Die Ankündigung einer Kapitalerhöhung hebt den Aktienkurs meist an.'),o:TF,a:1,w:L('Equity issues usually meet a negative reaction: managers issue when they think shares are expensive.','Kapitalerhöhungen werden meist negativ aufgenommen: Manager geben Aktien aus, wenn sie sie für teuer halten.')},
 {q:L('If the premium paid exceeds the synergies, the acquirer’s value falls.','Übersteigt die gezahlte Prämie die Synergien, sinkt der Wert des Käufers.'),o:TF,a:0,w:L('Acquirer gain = synergies − premium. Pay away more than you create and your own shareholders lose.','Gewinn des Käufers = Synergien − Prämie. Wer mehr weggibt, als er schafft, lässt die eigenen Aktionäre verlieren.')},
 {q:L('Cash-rich firms with few good projects tend to make value-destroying acquisitions.','Firmen mit viel Cash und wenigen guten Projekten machen tendenziell wertvernichtende Übernahmen.'),o:TF,a:0,w:L('Jensen’s free cash flow problem: spare cash invites empire building.','Jensens Free-Cashflow-Problem: überschüssiges Cash verleitet zum Empire Building.')},
 {q:L('Spin-offs on average lead to positive returns for the parent at announcement.','Spin-offs führen bei Ankündigung im Schnitt zu positiven Renditen der Muttergesellschaft.'),o:TF,a:0,w:L('Focus, clearer valuation and better incentives: the market usually welcomes them.','Fokus, klarere Bewertung, bessere Anreize: der Markt begrüßt sie meist.')},
 {q:L('Announcing a share buyback typically lifts the share price.','Die Ankündigung eines Aktienrückkaufs hebt den Kurs typischerweise an.'),o:TF,a:0,w:L('It signals that management sees the shares as cheap and returns spare cash.','Sie signalisiert, dass das Management die Aktien für günstig hält, und gibt überschüssiges Cash zurück.')},
 {q:L('A target under a cash bid falls back to roughly its undisturbed price if the deal is blocked.','Ein Target mit Barangebot fällt ungefähr auf seinen unbeeinflussten Kurs zurück, wenn der Deal untersagt wird.'),o:TF,a:0,w:L('Without the bid the premium disappears; sometimes it stays a little higher because the market expects another bidder.','Ohne Angebot verschwindet die Prämie; manchmal bleibt der Kurs etwas höher, weil der Markt einen anderen Bieter erwartet.')},
 {q:L('An AAA-rated buyer acquires a BB-rated target for cash and takes on its bonds. The target’s bonds…','Ein Käufer mit AAA-Rating übernimmt ein Target mit BB-Rating in bar und übernimmt dessen Anleihen. Die Target-Anleihen…'),o:DIR3,a:0,w:L('Backed by a much stronger issuer: spreads tighten, prices rise.','Durch einen viel stärkeren Emittenten gedeckt: Spreads sinken, Kurse steigen.')},
 {q:L('A PE fund buys a BBB company and adds 5× debt. The old bonds have no change-of-control clause. They…','Ein PE-Fonds kauft eine BBB-Firma und legt 5× Schulden auf. Die alten Anleihen haben keine Change-of-Control-Klausel. Sie…'),o:DIR3,a:1,w:L('Same claims, much more debt ahead of or beside them: default risk up, price down.','Gleiche Ansprüche, viel mehr Schulden daneben: Ausfallrisiko steigt, Kurs fällt.')},
 {q:L('A rival bidder appears at a higher price. The target’s share price…','Ein konkurrierender Bieter taucht mit höherem Preis auf. Der Target-Kurs…'),o:DIR3,a:0,w:L('It moves towards the new, higher offer.','Er bewegt sich Richtung des neuen, höheren Angebots.')},
 {q:L('The antitrust authority opens an in-depth investigation. The merger arbitrage spread…','Die Kartellbehörde leitet eine vertiefte Prüfung ein. Der Merger-Arbitrage-Spread…'),o:DIR3,a:0,w:L('Higher risk of failure and a longer wait: the target falls further below the offer, the spread widens.','Höheres Scheiterrisiko und längere Wartezeit: das Target fällt weiter unter das Angebot, der Spread wird größer.')},
 {q:L('A large acquirer announces a 40% premium deal paid in stock, with no synergies disclosed. On average its share price…','Ein großer Käufer kündigt einen Deal mit 40 % Prämie an, bezahlt in Aktien, ohne genannte Synergien. Im Schnitt reagiert sein Kurs…'),o:DIR3,a:1,w:L('High premium, stock currency, no synergy story: the typical recipe for a negative reaction.','Hohe Prämie, Aktien als Währung, keine Synergie-Story: das typische Rezept für eine negative Reaktion.')},
 {q:L('The acquirer funds a large deal with new bonds and is downgraded to BBB−. Its existing bonds…','Der Käufer finanziert einen großen Deal mit neuen Anleihen und wird auf BBB− herabgestuft. Seine bestehenden Anleihen…'),o:DIR3,a:1,w:L('Weaker credit, wider spreads, lower prices.','Schwächere Bonität, höhere Spreads, niedrigere Kurse.')},
 {q:L('The target’s bonds mature in two months and will be repaid at closing anyway. A strong acquirer bids. The bond price…','Die Target-Anleihen werden in zwei Monaten fällig und beim Closing ohnehin zurückgezahlt. Ein starker Käufer bietet. Der Anleihekurs…'),o:DIR3,a:2,w:L('Almost no time left and repayment is certain: the price barely moves.','Kaum Restlaufzeit, Rückzahlung sicher: der Kurs bewegt sich kaum.')},
 {q:L('A cash offer is announced at a 30% premium. The target’s share price…','Ein Barangebot mit 30 % Prämie wird angekündigt. Der Target-Kurs…'),o:DIR3,a:0,w:L('It jumps towards the offer price, minus a small arbitrage spread.','Er springt Richtung Angebotspreis, abzüglich eines kleinen Arbitrage-Spreads.')},
 {q:L('Target bonds have a change-of-control put at 101% and trade at 90 before an LBO is announced. They…','Target-Anleihen haben einen Change-of-Control-Put zu 101 % und notieren vor Ankündigung eines LBO bei 90. Sie…'),o:DIR3,a:0,w:L('They can be put back at 101 after closing, so the price rises towards 101.','Sie können nach dem Closing zu 101 zurückgegeben werden; der Kurs steigt Richtung 101.')}
];

var EXCEL_BANK=[
 {q:L('Windows: make a cell reference absolute ($A$1) while editing a formula.','Windows: einen Zellbezug beim Bearbeiten absolut machen ($A$1).'),o:['F4','F2','Ctrl + $','Alt + A'],a:0,w:L('F4 cycles through $A$1, A$1, $A1 and A1.','F4 wechselt zwischen $A$1, A$1, $A1 und A1.')},
 {q:L('Mac: make a cell reference absolute while editing a formula.','Mac: einen Zellbezug beim Bearbeiten absolut machen.'),o:['⌘ + T','⌘ + 4','F4 only','⌘ + $'],a:0,w:L('On a Mac it is ⌘ + T (or fn + F4 on some setups).','Auf dem Mac ist es ⌘ + T (oder fn + F4 je nach Einstellung).')},
 {q:L('Windows: open “Format Cells”.','Windows: „Zellen formatieren“ öffnen.'),o:['Ctrl + 1','Ctrl + F','Alt + F','Ctrl + Shift + F'],a:0,w:L('Ctrl + 1 (⌘ + 1 on Mac).','Strg + 1 (⌘ + 1 auf dem Mac).')},
 {q:L('Windows: copy the cell above into the selected cells below.','Windows: die Zelle darüber in die markierten Zellen darunter kopieren.'),o:['Ctrl + D','Ctrl + R','Ctrl + Enter','Ctrl + B'],a:0,w:L('Ctrl + D fills down, Ctrl + R fills right.','Strg + D füllt nach unten, Strg + R nach rechts.')},
 {q:L('Windows: fill the selection to the right with the left-most cell.','Windows: die Markierung mit der linken Zelle nach rechts füllen.'),o:['Ctrl + R','Ctrl + D','Ctrl + →','Shift + R'],a:0,w:L('Ctrl + R = fill right.','Strg + R = nach rechts füllen.')},
 {q:L('Windows: switch filters on or off for a table.','Windows: Filter für eine Tabelle ein- oder ausschalten.'),o:['Ctrl + Shift + L','Ctrl + L','Alt + F','Ctrl + Shift + F'],a:0,w:L('Ctrl + Shift + L (⌘ + Shift + F on Mac).','Strg + Umschalt + L (⌘ + Umschalt + F auf dem Mac).')},
 {q:L('Windows: insert a SUM of the cells above.','Windows: eine SUMME der Zellen darüber einfügen.'),o:['Alt + =','Ctrl + S','Ctrl + =','Alt + S'],a:0,w:L('Alt + = inserts AutoSum.','Alt + = fügt AutoSumme ein.')},
 {q:L('Jump to the last filled cell in a column.','Zur letzten gefüllten Zelle einer Spalte springen.'),o:['Ctrl + ↓','Page Down','Shift + ↓','End'],a:0,w:L('Ctrl + arrow jumps to the edge of the data block.','Strg + Pfeil springt an den Rand des Datenblocks.')},
 {q:L('Select from the current cell to the end of the data in a row.','Von der aktuellen Zelle bis zum Ende der Daten einer Zeile markieren.'),o:['Ctrl + Shift + →','Shift + →','Ctrl + →','Alt + Shift + →'],a:0,w:L('Add Shift to Ctrl + arrow to extend the selection.','Umschalt zu Strg + Pfeil erweitert die Markierung.')},
 {q:L('Select the whole row of the active cell.','Die ganze Zeile der aktiven Zelle markieren.'),o:['Shift + Space','Ctrl + Space','Ctrl + A','Alt + Space'],a:0,w:L('Shift + Space = row, Ctrl + Space = column.','Umschalt + Leertaste = Zeile, Strg + Leertaste = Spalte.')},
 {q:L('Select the whole column of the active cell.','Die ganze Spalte der aktiven Zelle markieren.'),o:['Ctrl + Space','Shift + Space','Ctrl + C','Alt + ↓'],a:0,w:L('Ctrl + Space = column.','Strg + Leertaste = Spalte.')},
 {q:L('Windows: show all formulas instead of values.','Windows: alle Formeln statt Werten anzeigen.'),o:['Ctrl + `','Ctrl + F','F9','Ctrl + Shift + F'],a:0,w:L('Ctrl + ` (grave accent) toggles formula view.','Strg + ` (Gravis) schaltet die Formelansicht um.')},
 {q:L('Windows: jump to the cells a formula refers to (precedents).','Windows: zu den Zellen springen, auf die eine Formel verweist (Vorgänger).'),o:['Ctrl + [','Ctrl + ]','F5','Alt + P'],a:0,w:L('Ctrl + [ goes to direct precedents, Ctrl + ] to dependents.','Strg + [ springt zu direkten Vorgängern, Strg + ] zu Nachfolgern.')},
 {q:L('Windows: go to the next worksheet.','Windows: zum nächsten Tabellenblatt wechseln.'),o:['Ctrl + Page Down','Ctrl + Tab','Alt + →','Ctrl + N'],a:0,w:L('Ctrl + Page Down / Page Up moves between sheets.','Strg + Bild ab / Bild auf wechselt zwischen Blättern.')},
 {q:L('Edit the active cell without retyping it.','Die aktive Zelle bearbeiten, ohne neu zu tippen.'),o:['F2','F4','F9','F12'],a:0,w:L('F2 enters edit mode.','F2 öffnet den Bearbeitungsmodus.')},
 {q:L('Windows: insert today’s date as a fixed value.','Windows: das heutige Datum als festen Wert einfügen.'),o:['Ctrl + ;','=TODAY()','Ctrl + D','Ctrl + Shift + D'],a:0,w:L('Ctrl + ; inserts a static date; =TODAY() updates every day.','Strg + ; fügt ein festes Datum ein; =HEUTE() ändert sich jeden Tag.')},
 {q:L('Windows: open Paste Special.','Windows: Inhalte einfügen öffnen.'),o:['Ctrl + Alt + V','Ctrl + Shift + V','Alt + V','Ctrl + P'],a:0,w:L('Ctrl + Alt + V (legacy: Alt, E, S).','Strg + Alt + V (alt: Alt, E, S).')},
 {q:L('Start a new line inside the same cell.','Eine neue Zeile in derselben Zelle beginnen.'),o:['Alt + Enter','Shift + Enter','Ctrl + Enter','Tab'],a:0,w:L('Alt + Enter (⌥ + Enter on Mac). Ctrl + Enter fills the selection.','Alt + Enter (⌥ + Enter auf dem Mac). Strg + Enter füllt die Markierung.')},
 {q:L('Enter the same value in every selected cell at once.','Denselben Wert in alle markierten Zellen gleichzeitig eingeben.'),o:['Ctrl + Enter','Alt + Enter','Shift + Enter','Ctrl + D'],a:0,w:L('Type, then Ctrl + Enter.','Tippen, dann Strg + Enter.')},
 {q:L('Windows: insert rows or cells.','Windows: Zeilen oder Zellen einfügen.'),o:['Ctrl + Shift + +','Ctrl + I','Alt + I','Ctrl + −'],a:0,w:L('Ctrl + Shift + + inserts, Ctrl + − deletes.','Strg + Umschalt + + fügt ein, Strg + − löscht.')},
 {q:L('Recalculate all formulas when calculation is set to manual.','Alle Formeln neu berechnen, wenn die Berechnung auf manuell steht.'),o:['F9','F5','F2','Ctrl + R'],a:0,w:L('F9 calculates; models with circularity often run on manual.','F9 berechnet; Modelle mit Zirkelbezug laufen oft auf manuell.')},
 {q:L('Windows: number format with thousands separator and two decimals.','Windows: Zahlenformat mit Tausendertrennzeichen und zwei Nachkommastellen.'),o:['Ctrl + Shift + 1','Ctrl + Shift + 5','Ctrl + 1','Ctrl + Shift + 4'],a:0,w:L('Ctrl + Shift + 1. (+5 is percent, +4 is currency.)','Strg + Umschalt + 1. (+5 ist Prozent, +4 ist Währung.)')},
 {q:L('Revenue is in B4 (2025) and C4 (2026). Growth in 2026?','Umsatz steht in B4 (2025) und C4 (2026). Wachstum 2026?'),o:['=C4/B4-1','=B4/C4-1','=C4-B4/B4','=(C4-B4)/C4'],a:0,w:L('=C4/B4−1. Careful: =C4−B4/B4 divides first because of operator precedence.','=C4/B4−1. Vorsicht: =C4−B4/B4 teilt zuerst, wegen der Rechenregeln.')},
 {q:L('Revenue 2021 in B4, 2025 in F4. CAGR?','Umsatz 2021 in B4, 2025 in F4. CAGR?'),o:['=(F4/B4)^(1/4)-1','=(F4/B4)^(1/5)-1','=(F4-B4)/B4/4','=F4/B4^(1/4)-1'],a:0,w:L('2021 to 2025 is four years of growth, so the power is 1/4. Brackets matter.','2021 bis 2025 sind vier Wachstumsjahre, also Exponent 1/4. Klammern sind wichtig.')},
 {q:L('The tax rate is in B2. You copy the tax formula from C6 across to G6. What should C6 be?','Der Steuersatz steht in B2. Du kopierst die Steuerformel von C6 bis G6. Wie sollte C6 lauten?'),o:['=C5*$B$2','=C5*B2','=$C$5*B2','=C$5*B$2'],a:0,w:L('Lock the tax rate with $B$2; leave C5 relative so it moves with the column.','Steuersatz mit $B$2 fixieren; C5 relativ lassen, damit es mit der Spalte wandert.')},
 {q:L('A sensitivity table: rates in column A, years in row 1. Which formula copies correctly to every cell (B2 shown)?','Eine Sensitivitätstabelle: Zinsen in Spalte A, Jahre in Zeile 1. Welche Formel lässt sich in jede Zelle kopieren (B2 gezeigt)?'),o:['=$A2*B$1','=A2*B1','=$A$2*$B$1','=A$2*$B1'],a:0,w:L('Fix the column for the rate ($A) and the row for the year ($1).','Spalte für den Zins ($A) und Zeile für das Jahr ($1) fixieren.')},
 {q:L('Cash flows: year 0 in B5, years 1–5 in C5:G5, rate in B2. Correct NPV?','Cashflows: Jahr 0 in B5, Jahre 1–5 in C5:G5, Zins in B2. Richtiger Barwert (NPV)?'),o:['=NPV(B2,C5:G5)+B5','=NPV(B2,B5:G5)','=NPV(B2,B5:G5)+B5','=B5+NPV(B2,B5:G5)/(1+B2)'],a:0,w:L('Excel’s NPV discounts the first value by one period, so add year 0 separately.','Excels NPV diskontiert den ersten Wert um eine Periode; Jahr 0 also separat addieren.')},
 {q:L('Cash flows on irregular dates. Which function gives the right IRR?','Cashflows an unregelmäßigen Terminen. Welche Funktion liefert die richtige IRR?'),o:['XIRR','IRR','MIRR','RATE'],a:0,w:L('XIRR uses the actual dates; IRR assumes equal periods.','XIRR nutzt die echten Daten; IRR unterstellt gleich lange Perioden.')},
 {q:L('You need a value from a column to the LEFT of the lookup column.','Du brauchst einen Wert aus einer Spalte LINKS der Suchspalte.'),o:['INDEX/MATCH or XLOOKUP','VLOOKUP','HLOOKUP','SUMIF'],a:0,w:L('VLOOKUP only looks to the right; INDEX/MATCH and XLOOKUP work in any direction.','SVERWEIS sucht nur nach rechts; INDEX/VERGLEICH und XVERWEIS in jede Richtung.')},
 {q:L('VLOOKUP returns a value for a name that is not in the list. Most likely cause?','SVERWEIS liefert einen Wert für einen Namen, der nicht in der Liste steht. Wahrscheinlichste Ursache?'),o:[L('Last argument missing (approximate match)','Letztes Argument fehlt (ungefähre Suche)'),L('Wrong column number','Falsche Spaltennummer'),L('Absolute reference','Absoluter Bezug'),L('Calculation on manual','Berechnung auf manuell')],a:0,w:L('Without FALSE/0 VLOOKUP does an approximate match and returns a neighbour.','Ohne FALSCH/0 sucht SVERWEIS ungefähr und liefert einen Nachbarn.')},
 {q:L('Sum column C where column A is “DE” and column B is 2026.','Spalte C summieren, wenn Spalte A „DE“ ist und Spalte B 2026.'),o:['=SUMIFS(C:C,A:A,"DE",B:B,2026)','=SUMIF(A:A,"DE",C:C,B:B,2026)','=SUMIFS(A:A,"DE",B:B,2026,C:C)','=SUM(IF(A:A="DE",C:C))'],a:0,w:L('SUMIFS puts the sum range first, then pairs of range and criterion.','SUMMEWENNS nennt zuerst den Summenbereich, dann Paare aus Bereich und Kriterium.')},
 {q:L('Revolver draw in a model: minimum cash in B3, cash before revolver in C10.','Revolver-Ziehung im Modell: Mindestkasse in B3, Kasse vor Revolver in C10.'),o:['=MAX(0,$B$3-C10)','=MIN(0,$B$3-C10)','=MAX($B$3,C10)','=$B$3-C10'],a:0,w:L('Draw only if cash falls short of the minimum, never a negative draw.','Nur ziehen, wenn die Kasse unter dem Minimum liegt; nie negativ ziehen.')},
 {q:L('Cash sweep: cash available in C12, debt outstanding in C20. Repayment?','Cash Sweep: verfügbare Kasse in C12, ausstehende Schulden in C20. Tilgung?'),o:['=MIN(C12,C20)','=MAX(C12,C20)','=C12-C20','=MIN(0,C12)'],a:0,w:L('Repay as much as you can, but not more than the debt.','So viel tilgen wie möglich, aber nicht mehr als die Schulden.')},
 {q:L('Interest on the average debt balance makes the model show a circular reference warning. Best fix?','Zinsen auf den durchschnittlichen Schuldenstand lösen eine Zirkelbezug-Warnung aus. Beste Lösung?'),o:[L('Enable iterative calculation or use the opening balance, with a circuit breaker','Iterative Berechnung aktivieren oder Anfangsbestand nutzen, mit Schalter'),L('Delete the interest line','Zinszeile löschen'),L('Hard-code the interest','Zinsen fest eintippen'),L('Use IFERROR','WENNFEHLER nutzen')],a:0,w:L('Iteration (with a switch to break the loop) or opening balance interest are the standard answers.','Iteration (mit Schalter zum Unterbrechen) oder Zinsen auf den Anfangsbestand sind die Standardantworten.')},
 {q:L('A total row uses =SUM(B4:B12), but B8 is already a subtotal of B4:B7. What happens?','Eine Summenzeile nutzt =SUMME(B4:B12), aber B8 ist schon eine Zwischensumme von B4:B7. Was passiert?'),o:[L('B4:B7 is counted twice','B4:B7 wird doppelt gezählt'),L('Nothing, SUM skips subtotals','Nichts, SUMME überspringt Zwischensummen'),L('#REF! error','#BEZUG!-Fehler'),L('Circular reference','Zirkelbezug')],a:0,w:L('SUM adds everything; use SUBTOTAL or sum only the subtotals.','SUMME addiert alles; TEILERGEBNIS nutzen oder nur die Zwischensummen addieren.')},
 {q:L('A cell shows #REF!. What happened?','Eine Zelle zeigt #BEZUG! (#REF!). Was ist passiert?'),o:[L('A referenced cell was deleted','Eine referenzierte Zelle wurde gelöscht'),L('Division by zero','Division durch null'),L('Lookup found nothing','Suche fand nichts'),L('Text instead of a number','Text statt Zahl')],a:0,w:L('#DIV/0! is division by zero, #N/A a failed lookup, #VALUE! the wrong type.','#DIV/0! ist Division durch null, #NV eine erfolglose Suche, #WERT! der falsche Datentyp.')},
 {q:L('A cell shows #N/A after a lookup. What does it mean?','Eine Zelle zeigt #NV (#N/A) nach einer Suche. Was bedeutet das?'),o:[L('The value was not found','Der Wert wurde nicht gefunden'),L('A cell was deleted','Eine Zelle wurde gelöscht'),L('Division by zero','Division durch null'),L('The function name is misspelled','Der Funktionsname ist falsch geschrieben')],a:0,w:L('#NAME? is the misspelled function.','#NAME? ist der falsch geschriebene Funktionsname.')},
 {q:L('Why is wrapping every formula in IFERROR(…,0) a bad habit in a model?','Warum ist es schlecht, jede Formel im Modell in WENNFEHLER(…;0) zu packen?'),o:[L('It hides real errors as zeros','Es versteckt echte Fehler als Nullen'),L('It slows Excel down a lot','Es macht Excel sehr langsam'),L('It breaks absolute references','Es zerstört absolute Bezüge'),L('It is not allowed in tables','Es ist in Tabellen nicht erlaubt')],a:0,w:L('A broken link then shows 0 and nobody notices.','Ein kaputter Verweis zeigt dann 0, und niemand merkt es.')},
 {q:L('Last day of the month for a date in A1?','Letzter Tag des Monats für ein Datum in A1?'),o:['=EOMONTH(A1,0)','=EDATE(A1,1)','=MONTH(A1)+1','=DATE(A1,0)'],a:0,w:L('EOMONTH(date,0) is month end; EDATE shifts by whole months.','MONATSENDE(Datum;0) ist das Monatsende; EDATUM verschiebt um ganze Monate.')},
 {q:L('Look up a value by row AND column header (e.g. EBITDA for 2026) without hard-coding the column number.','Einen Wert über Zeilen- UND Spaltenüberschrift suchen (z. B. EBITDA für 2026), ohne die Spaltennummer fest einzutippen.'),o:['=INDEX(B2:F20,MATCH("EBITDA",A2:A20,0),MATCH(2026,B1:F1,0))','=VLOOKUP("EBITDA",A2:F20,3,0)','=INDEX(A2:F20,"EBITDA",2026)','=MATCH("EBITDA",A2:A20,2026)'],a:0,w:L('INDEX with two MATCHes finds the cell at the crossing of row and column; nothing breaks when columns are inserted.','INDEX mit zwei VERGLEICH findet die Zelle im Schnittpunkt von Zeile und Spalte; nichts bricht, wenn Spalten eingefügt werden.')},
 {q:L('What does =MATCH("EBITDA",A1:A50,0) return?','Was liefert =VERGLEICH("EBITDA";A1:A50;0)?'),o:[L('The position of “EBITDA” in the range','Die Position von „EBITDA“ im Bereich'),L('The EBITDA value','Den EBITDA-Wert'),L('TRUE or FALSE','WAHR oder FALSCH'),L('The cell address','Die Zelladresse')],a:0,w:L('MATCH returns a position; INDEX then turns it into a value. 0 = exact match.','VERGLEICH liefert eine Position; INDEX macht daraus den Wert. 0 = genaue Übereinstimmung.')},
 {q:L('Why do many bankers prefer INDEX/MATCH to VLOOKUP?','Warum bevorzugen viele Banker INDEX/VERGLEICH gegenüber SVERWEIS?'),o:[L('It can look left and does not break when columns are inserted','Es sucht auch nach links und bricht nicht, wenn Spalten eingefügt werden'),L('It is always exact','Es ist immer exakt'),L('It works without ranges','Es braucht keine Bereiche'),L('It is the only function that ignores errors','Es ist die einzige Funktion, die Fehler ignoriert')],a:0,w:L('VLOOKUP uses a fixed column number, which silently points to the wrong column after an insert.','SVERWEIS nutzt eine feste Spaltennummer, die nach dem Einfügen stillschweigend auf die falsche Spalte zeigt.')},
 {q:L('What does =OFFSET(B5,0,2) return?','Was liefert =BEREICH.VERSCHIEBEN(B5;0;2) (OFFSET)?'),o:[L('The value in D5','Den Wert in D5'),L('The value in B7','Den Wert in B7'),L('The sum of B5:D5','Die Summe von B5:D5'),L('The value in C6','Den Wert in C6')],a:0,w:L('OFFSET(reference, rows, columns): 0 rows down, 2 columns right of B5 → D5.','BEREICH.VERSCHIEBEN(Bezug; Zeilen; Spalten): 0 Zeilen nach unten, 2 Spalten nach rechts von B5 → D5.')},
 {q:L('Scenario switch: cell C2 holds 1, 2 or 3 (base, upside, downside). Pick the growth rate from rows 10–12.','Szenario-Schalter: Zelle C2 enthält 1, 2 oder 3 (Base, Upside, Downside). Wähle die Wachstumsrate aus den Zeilen 10–12.'),o:['=CHOOSE($C$2,D10,D11,D12)','=IF(C2,D10,D11,D12)','=SUM(D10:D12)/$C$2','=INDEX(D10,D11,D12,C2)'],a:0,w:L('CHOOSE (or INDEX/OFFSET) with a fixed switch cell is the classic scenario toggle.','WAHL (oder INDEX/BEREICH.VERSCHIEBEN) mit fixierter Schalterzelle ist der klassische Szenario-Schalter.')},
 {q:L('Why is OFFSET used with care in large models?','Warum nutzt man BEREICH.VERSCHIEBEN (OFFSET) in großen Modellen mit Vorsicht?'),o:[L('It is volatile: it recalculates on every change and is hard to audit','Es ist volatil: es rechnet bei jeder Änderung neu und ist schwer nachzuvollziehen'),L('It cannot return ranges','Es kann keine Bereiche liefern'),L('It only works on one sheet','Es funktioniert nur auf einem Blatt'),L('It rounds numbers','Es rundet Zahlen')],a:0,w:L('OFFSET and INDIRECT are volatile; INDEX is usually the safer choice.','BEREICH.VERSCHIEBEN und INDIREKT sind volatil; INDEX ist meist die sicherere Wahl.')},
 {q:L('Sum the last 4 quarters where the latest quarter column number is in A1 (dynamic LTM).','Die letzten 4 Quartale summieren, wobei die Spaltennummer des letzten Quartals in A1 steht (dynamisches LTM).'),o:['=SUM(OFFSET(B5,0,$A$1-4,1,4))','=SUM(B5:E5)','=OFFSET(SUM(B5:E5),4)','=SUM(INDEX(B5,$A$1))'],a:0,w:L('OFFSET with height 1 and width 4 returns a moving 4-cell range.','BEREICH.VERSCHIEBEN mit Höhe 1 und Breite 4 liefert einen wandernden Bereich aus 4 Zellen.')},
 {q:L('XLOOKUP vs VLOOKUP: which statement is true?','XVERWEIS vs. SVERWEIS: welche Aussage stimmt?'),o:[L('XLOOKUP defaults to exact match and can look left','XVERWEIS sucht standardmäßig exakt und auch nach links'),L('XLOOKUP needs a column number','XVERWEIS braucht eine Spaltennummer'),L('XLOOKUP only works on sorted data','XVERWEIS funktioniert nur mit sortierten Daten'),L('They are identical','Sie sind identisch')],a:0,w:L('XLOOKUP(lookup, lookup range, return range): exact by default, any direction, optional “not found” value.','XVERWEIS(Suchkriterium; Suchbereich; Rückgabebereich): standardmäßig exakt, in jede Richtung, optionaler Wert für „nicht gefunden“.')},
 {q:L('Weighted average margin: margins in C5:C9, revenues in B5:B9.','Gewichtete Durchschnittsmarge: Margen in C5:C9, Umsätze in B5:B9.'),o:['=SUMPRODUCT(B5:B9,C5:C9)/SUM(B5:B9)','=AVERAGE(C5:C9)','=SUM(C5:C9)/SUM(B5:B9)','=PRODUCT(B5:C9)/5'],a:0,w:L('SUMPRODUCT weights each margin by its revenue; a plain average ignores size.','SUMMENPRODUKT gewichtet jede Marge mit ihrem Umsatz; ein einfacher Durchschnitt ignoriert die Größe.')},
 {q:L('You want the exit multiple that gives exactly 20% IRR. Fastest Excel tool?','Du suchst das Exit-Multiple, das genau 20 % IRR ergibt. Schnellstes Excel-Werkzeug?'),o:[L('Goal Seek','Zielwertsuche'),L('Data table','Datentabelle'),L('Pivot table','Pivot-Tabelle'),L('Conditional formatting','Bedingte Formatierung')],a:0,w:L('Goal Seek changes one input until an output hits a target. A data table shows a grid of outcomes.','Die Zielwertsuche ändert einen Input, bis ein Output einen Zielwert trifft. Eine Datentabelle zeigt ein Raster von Ergebnissen.')},
 {q:L('Sensitivity table of IRR for exit multiple × leverage. Which tool?','Sensitivitätstabelle der IRR für Exit-Multiple × Verschuldung. Welches Werkzeug?'),o:[L('Data table (What-If analysis)','Datentabelle (Was-wäre-wenn-Analyse)'),L('Goal Seek','Zielwertsuche'),L('Solver','Solver'),L('Text to columns','Text in Spalten')],a:0,w:L('A two-variable data table recalculates the model for every pair of inputs.','Eine Datentabelle mit zwei Variablen rechnet das Modell für jedes Input-Paar neu.')},
 {q:L('=INDIRECT("Sheet2!B"&A1) is mainly risky because…','=INDIREKT("Blatt2!B"&A1) ist vor allem riskant, weil…'),o:[L('the reference is text: it breaks silently when sheets or rows change, and it is volatile','der Bezug Text ist: er bricht still, wenn Blätter oder Zeilen sich ändern, und er ist volatil'),L('it cannot read other sheets','es keine anderen Blätter lesen kann'),L('it only returns text','es nur Text liefert'),L('it is not available on Mac','es auf dem Mac nicht verfügbar ist')],a:0,w:L('Text references are not updated by Excel, and auditing tools cannot follow them.','Text-Bezüge passt Excel nicht an, und Prüfwerkzeuge können ihnen nicht folgen.')},
 {q:L('Colour convention in banking models: hard-coded inputs are usually…','Farbkonvention in Banking-Modellen: fest eingegebene Inputs sind meist…'),o:[L('Blue','Blau'),L('Black','Schwarz'),L('Green','Grün'),L('Red','Rot')],a:0,w:L('Blue inputs, black formulas, green links to other sheets.','Blaue Inputs, schwarze Formeln, grüne Verweise auf andere Blätter.')}
];

var UPDOWN_BANK=[
 {q:L('WACC rises. DCF enterprise value…','Der WACC steigt. DCF-Enterprise-Value…'),a:1,w:L('Future cash flows are discounted more.','Künftige Cashflows werden stärker abgezinst.')},
 {q:L('Terminal growth rate rises. Terminal value…','Die ewige Wachstumsrate steigt. Terminal Value…'),a:0,w:L('TV = FCF × (1+g) ÷ (WACC − g): both terms push it up.','TV = FCF × (1+g) ÷ (WACC − g): beide Terme treiben ihn nach oben.')},
 {q:L('Beta rises. Cost of equity…','Das Beta steigt. Eigenkapitalkosten…'),a:0,w:L('CAPM: risk-free + beta × market premium.','CAPM: risikoloser Zins + Beta × Marktprämie.')},
 {q:L('The tax rate rises. After-tax cost of debt…','Der Steuersatz steigt. Fremdkapitalkosten nach Steuern…'),a:1,w:L('Kd × (1 − t): a bigger tax shield.','Kd × (1 − t): ein größeres Steuerschild.')},
 {q:L('The risk-free rate rises, all else equal. WACC…','Der risikolose Zins steigt, alles andere gleich. WACC…'),a:0,w:L('It lifts both the cost of equity and the cost of debt.','Er hebt Eigen- und Fremdkapitalkosten.')},
 {q:L('The company raises a bond and keeps the cash. Enterprise value…','Die Firma begibt eine Anleihe und behält das Cash. Enterprise Value…'),a:2,w:L('Debt up, cash up by the same amount: they cancel in the bridge.','Schulden und Kasse steigen gleich stark: sie heben sich in der Bridge auf.')},
 {q:L('The company pays a cash dividend. Enterprise value…','Die Firma zahlt eine Bardividende. Enterprise Value…'),a:2,w:L('Equity value and cash both fall by the dividend; EV stays.','Equity Value und Kasse sinken beide um die Dividende; der EV bleibt.')},
 {q:L('The company pays a cash dividend. Equity value…','Die Firma zahlt eine Bardividende. Equity Value…'),a:1,w:L('Cash leaves the company and goes to shareholders.','Cash verlässt die Firma und geht an die Aktionäre.')},
 {q:L('The company buys back shares with cash. Enterprise value…','Die Firma kauft Aktien mit Cash zurück. Enterprise Value…'),a:2,w:L('Equity value falls by the cash spent, cash falls the same: EV unchanged.','Equity Value sinkt um das ausgegebene Cash, die Kasse ebenso: EV unverändert.')},
 {q:L('Equity value stays the same, minority interest rises. Enterprise value…','Equity Value bleibt gleich, Minderheitsanteile steigen. Enterprise Value…'),a:0,w:L('Minorities are added in the bridge.','Minderheiten werden in der Bridge addiert.')},
 {q:L('EV stays the same, the pension deficit rises. Equity value…','Der EV bleibt gleich, das Pensionsdefizit steigt. Equity Value…'),a:1,w:L('Pensions are debt-like and come off EV.','Pensionen sind schuldenähnlich und gehen vom EV ab.')},
 {q:L('The share price rises. Diluted share count under the treasury stock method…','Der Aktienkurs steigt. Verwässerte Aktienzahl nach der Treasury-Stock-Methode…'),a:0,w:L('Fewer shares can be bought back with the option proceeds, and more options are in the money.','Mit den Optionserlösen lassen sich weniger Aktien zurückkaufen, und mehr Optionen sind im Geld.')},
 {q:L('The option strike price rises. Diluted share count…','Der Ausübungspreis der Optionen steigt. Verwässerte Aktienzahl…'),a:1,w:L('Higher proceeds buy back more shares, or the options fall out of the money.','Höhere Erlöse kaufen mehr Aktien zurück, oder die Optionen fallen aus dem Geld.')},
 {q:L('Working capital increases. Free cash flow…','Das Working Capital steigt. Free Cashflow…'),a:1,w:L('Cash is tied up in receivables and inventory.','Cash ist in Forderungen und Vorräten gebunden.')},
 {q:L('CapEx rises. Free cash flow…','Die Investitionen steigen. Free Cashflow…'),a:1,w:L('More cash out the door.','Mehr Cash fließt ab.')},
 {q:L('Tax-deductible depreciation rises, EBITDA unchanged. Free cash flow…','Steuerlich absetzbare Abschreibungen steigen, EBITDA unverändert. Free Cashflow…'),a:0,w:L('Lower taxes; depreciation itself is non-cash.','Weniger Steuern; die Abschreibung selbst ist nicht zahlungswirksam.')},
 {q:L('Depreciation rises. Net income…','Die Abschreibungen steigen. Jahresüberschuss…'),a:1,w:L('An expense, partly offset by lower tax.','Ein Aufwand, teils ausgeglichen durch weniger Steuern.')},
 {q:L('Stock deal: the P/E paid for the target rises. EPS accretion…','Aktien-Deal: das für das Target gezahlte KGV steigt. EPS-Accretion…'),a:1,w:L('You buy less earnings per share issued.','Man kauft weniger Gewinn je ausgegebener Aktie.')},
 {q:L('Stock deal: the acquirer’s P/E rises. EPS accretion…','Aktien-Deal: das KGV des Käufers steigt. EPS-Accretion…'),a:0,w:L('Its currency is more valuable: fewer new shares.','Seine Währung ist wertvoller: weniger neue Aktien.')},
 {q:L('Debt-funded deal: the interest rate rises. EPS accretion…','Schuldenfinanzierter Deal: der Zins steigt. EPS-Accretion…'),a:1,w:L('Higher after-tax interest cost.','Höhere Zinskosten nach Steuern.')},
 {q:L('Debt-funded deal: the tax rate rises. After-tax interest cost…','Schuldenfinanzierter Deal: der Steuersatz steigt. Zinskosten nach Steuern…'),a:1,w:L('Interest is tax-deductible.','Zinsen sind steuerlich absetzbar.')},
 {q:L('Expected synergies rise. EPS accretion…','Die erwarteten Synergien steigen. EPS-Accretion…'),a:0,w:L('More pro forma earnings.','Mehr Pro-forma-Gewinn.')},
 {q:L('LBO: more debt at entry, same entry and exit values. Equity IRR…','LBO: mehr Schulden beim Einstieg, gleiche Ein- und Ausstiegswerte. Equity-IRR…'),a:0,w:L('Less equity in, the same value gain: leverage boosts returns (and risk).','Weniger Eigenkapital, gleicher Wertzuwachs: Hebel steigert Rendite (und Risiko).')},
 {q:L('LBO: the same money multiple over a longer holding period. IRR…','LBO: gleicher Money Multiple über eine längere Haltedauer. IRR…'),a:1,w:L('The same gain spread over more years.','Derselbe Gewinn verteilt auf mehr Jahre.')},
 {q:L('LBO: a higher entry multiple, same exit. IRR…','LBO: höheres Einstiegsmultiple, gleicher Exit. IRR…'),a:1,w:L('You pay more for the same exit.','Man zahlt mehr für denselben Exit.')},
 {q:L('LBO: a dividend recap in year 2 instead of the same cash at exit. IRR…','LBO: eine Dividenden-Rekapitalisierung in Jahr 2 statt derselben Summe beim Exit. IRR…'),a:0,w:L('Money back earlier raises IRR; the money multiple stays the same.','Früher zurückgezahltes Geld hebt die IRR; der Money Multiple bleibt gleich.')},
 {q:L('LBO: the exit multiple rises. Money multiple…','LBO: das Exit-Multiple steigt. Money Multiple…'),a:0,w:L('Higher exit value, same debt.','Höherer Exit-Wert, gleiche Schulden.')},
 {q:L('Interest rates rise. Bond prices…','Die Zinsen steigen. Anleihekurse…'),a:1,w:L('Fixed coupons are worth less when new bonds pay more.','Feste Kupons sind weniger wert, wenn neue Anleihen mehr zahlen.')},
 {q:L('A bond’s credit rating is upgraded. Its credit spread…','Das Rating einer Anleihe wird heraufgestuft. Ihr Credit Spread…'),a:1,w:L('Lower risk, lower spread, higher price.','Weniger Risiko, niedrigerer Spread, höherer Kurs.')},
 {q:L('The market-implied probability of a deal closing rises. The target’s share price…','Die vom Markt implizierte Abschlusswahrscheinlichkeit steigt. Der Target-Kurs…'),a:0,w:L('Price = undisturbed + probability × (offer − undisturbed).','Kurs = unbeeinflusst + Wahrscheinlichkeit × (Angebot − unbeeinflusst).')},
 {q:L('A company sells a non-core division for cash at fair value. Enterprise value of the remaining business…','Eine Firma verkauft einen Randbereich zum fairen Wert gegen Cash. Enterprise Value des verbleibenden Geschäfts…'),a:1,w:L('Fewer operating assets; the cash is subtracted in the bridge.','Weniger operatives Vermögen; das Cash wird in der Bridge abgezogen.')},
 {q:L('Goodwill is impaired. Cash…','Der Goodwill wird abgeschrieben. Kasse…'),a:2,w:L('A non-cash charge (and usually not tax-deductible).','Ein nicht zahlungswirksamer Aufwand (meist nicht steuerlich absetzbar).')},
 {q:L('Goodwill is impaired. Equity on the balance sheet…','Der Goodwill wird abgeschrieben. Eigenkapital in der Bilanz…'),a:1,w:L('The loss reduces retained earnings.','Der Verlust mindert die Gewinnrücklagen.')},
 {q:L('Inventory is bought on credit. Total assets…','Vorräte werden auf Ziel gekauft. Bilanzsumme…'),a:0,w:L('Inventory up, payables up: balance sheet extension.','Vorräte und Verbindlichkeiten steigen: Bilanzverlängerung.')},
 {q:L('A customer pays an existing receivable. Total assets…','Ein Kunde zahlt eine bestehende Forderung. Bilanzsumme…'),a:2,w:L('Cash up, receivables down: asset swap.','Kasse hoch, Forderungen runter: Aktivtausch.')},
 {q:L('A supplier invoice is paid. Total assets…','Eine Lieferantenrechnung wird bezahlt. Bilanzsumme…'),a:1,w:L('Cash and payables both fall: balance sheet contraction.','Kasse und Verbindlichkeiten sinken: Bilanzverkürzung.')},
 {q:L('Under IFRS 16 a company now capitalises its leases. EBITDA…','Unter IFRS 16 aktiviert eine Firma ihre Leasingverträge. EBITDA…'),a:0,w:L('Rent leaves operating costs; depreciation and interest replace it below EBITDA.','Miete fällt aus den operativen Kosten; Abschreibung und Zinsen ersetzen sie unterhalb des EBITDA.')},
 {q:L('Under IFRS 16 leases move onto the balance sheet. Net debt including leases…','Unter IFRS 16 kommen Leasingverträge in die Bilanz. Nettoverschuldung inkl. Leasing…'),a:0,w:L('Lease liabilities are added.','Leasingverbindlichkeiten kommen hinzu.')}
];
