/* Mental maths: numbers you meet in deal work. */
function mentalCard(){
  var t=r(0,7),q,a,s;
  if(t===0){var p=pick([5,10,12.5,15,20,25,30,35,40,60,75]),x=r(4,40)*20;a=x*p/100;q=f(p,1)+' % '+L('of','von')+' '+x;s=x+' × '+f(p/100,3)+' = '+f(a,2);}
  else if(t===1){var m=pick([6.5,7,7.5,8,8.5,9,9.5,11,12]),e=r(12,90);a=m*e;q=f(m,1)+' × '+e;s=f(a,1);}
  else if(t===2){var b=r(12,99),c=r(3,9);a=b*c;q=b+' × '+c;s=f(a,0);}
  else if(t===3){var d=pick([4,5,6,8,12,15,16,25]),k=r(6,60);a=k;q=(d*k)+' ÷ '+d;s=f(a,0);}
  else if(t===4){var x0=r(4,40)*10,g=pick([5,8,10,12,15,20,25,30,40,50]);var x1=x0*(1+g/100);a=g;q=L('Growth from ','Wachstum von ')+x0+L(' to ',' auf ')+f(x1,1)+' (%)';s='('+f(x1,1)+' ÷ '+x0+' − 1) = '+g+' %';}
  else if(t===5){var fr=pick([[1,8],[3,8],[5,8],[7,8],[1,6],[5,6],[1,3],[2,3],[3,16],[7,16]]);a=fr[0]/fr[1]*100;q=fr[0]+'/'+fr[1]+L(' as a percentage',' in Prozent');s=f(a,2)+' %';}
  else if(t===6){var x=r(20,90)*10,tx=pick([25,30,15]);a=x*(1-tx/100);q=x+L(' after ',' nach ')+tx+L('% tax',' % Steuer');s=x+' × '+f(1-tx/100,2)+' = '+f(a,1);}
  else{var y=pick([[1.1,2],[1.1,3],[1.2,2],[1.05,2],[1.5,2],[2,0.5]]);a=Math.pow(y[0],y[1]);q=f(y[0],2)+' ^ '+f(y[1],1);s=f(a,4);}
  return {q:q,num:a,tol:Math.max(0.01,Math.abs(a)*0.005),w:s};
}
